import {isPresent} from './is-present.js';

/**
Assert that the given value is present (non-nullable), meaning it is neither `null` nor `undefined`.

If the value is not present (`undefined` or `null`), a helpful `TypeError` will be thrown.

@param message - Custom error message to use instead of the default.

@example
```
import {assertPresent} from 'ts-extras';

const unicorn = 'unicorn';
assertPresent(unicorn);

const notUnicorn = null;
assertPresent(notUnicorn);
//=> TypeError: Expected a present value, got `null`

assertPresent(notUnicorn, 'Unicorn is required');
//=> TypeError: Unicorn is required
```

@category Type guard
*/
export function assertPresent<T>(value: T, message?: string): asserts value is NonNullable<T> {
	if (!isPresent(value)) {
		// eslint-disable-next-line @typescript-eslint/restrict-template-expressions
		throw new TypeError(message ?? `Expected a present value, got \`${value}\``);
	}
}
const {toString} = Object.prototype;

function describeValue(value: unknown): string {
	try {
		return JSON.stringify(value);
	} catch {
		try {
			return String(value);
		} catch {
			try {
				return toString.call(value);
			} catch {
				return '<Unprintable value>';
			}
		}
	}
}

/**
Assert that the given value is an `Error`.

If the value is not an `Error`, a helpful `TypeError` will be thrown.

This can be useful as any value could potentially be thrown, but in practice, it's always an `Error`. However, because of this, TypeScript makes the caught error in a try/catch statement `unknown`, which is inconvenient to deal with.

@param message - Custom error message to use instead of the default.

@example
```
import {assertError} from 'ts-extras';

try {
	fetchUnicorns();
} catch (error: unknown) {
	assertError(error);

	// `error` is now of type `Error`

	if (error.message === 'Failed to fetch') {
		retry();
		return;
	}

	throw error;
}

assertError('not an error', 'Expected an Error instance');
//=> TypeError: Expected an Error instance
```

@category Type guard
*/
export function assertError(value: unknown, message?: string): asserts value is Error {
	// Cross-realm safe: either real instance or has the Error brand.
	if (value instanceof Error || toString.call(value) === '[object Error]') {
		return;
	}

	throw new TypeError(message ?? `Expected an Error, got ${toString.call(value)} (${typeof value}) → ${describeValue(value)}`);
}
/**
Assert that the given condition is truthy.

If the condition is falsy, an `Error` will be thrown. Because of the `asserts condition` signature, TypeScript narrows types based on the asserted condition.

@param message - Custom error message to use instead of the default.

@example
```
import {assert} from 'ts-extras';

const value = getValue() as string | undefined;

assert(value);
// `value` is now of type `string`

assert(value === 'unicorn', 'Expected a unicorn');
//=> Error: Expected a unicorn
```

@category Type guard
*/
export function assert(condition: unknown, message?: string): asserts condition {
	if (!condition) {
		throw new Error(message ?? 'Assertion failed');
	}
}
/**
Assert that a code path is unreachable.

Use this in the `default` case of a `switch` statement (or the final `else` of an `if`/`else if` chain) to get a compile-time error if a new variant is added to a union type but not handled.

If called at runtime (which should never happen), it throws an `Error` with the unexpected value.

@example
```
import {assertNever} from 'ts-extras';

type Status = 'idle' | 'loading' | 'success' | 'error';

function render(status: Status): string {
	switch (status) {
		case 'idle': {
			return 'Idle';
		}
		case 'loading': {
			return 'Loading...';
		}
		case 'success': {
			return 'Done';
		}
		case 'error': {
			return 'Failed';
		}
		default: {
			return assertNever(status);
		}
	}
}
```

@category Type guard
*/
export function assertNever(value: never): never {
	throw new Error(`Unreachable: \`${describeValue(value)}\``);
}

function describeValue(value: unknown): string {
	// Runtime misuse should still produce an Error even for values that cannot be string-coerced directly.
	try {
		return String(value);
	} catch {
		try {
			return Object.prototype.toString.call(value);
		} catch {
			return '<Unprintable value>';
		}
	}
}
